{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Lu 25-109, which shares the N-methyltetrahydropyridine motif and a five-membered heteroaromatic substituent, reached a 1:1 brain:blood ratio in rat microdialysis, demonstrating CNS penetration for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "CI-979, another N-methyltetrahydropyridine muscarinic agonist with a small heteroaromatic/oxime substituent, rapidly entered monkey brain in high concentrations (5-10% of IV dose), supporting CNS access for the query's core pharmacophore.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The deethylated tetrazole analogue Lu 31-126 was not detected in brain microdialysis, indicating that a more polar, acidic heteroaromatic variant can lose CNS penetration; however, the query's hexyloxy thiadiazole is more lipophilic and closer to the permeable analogues.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "A hexyl-substituted piperazine aryl compound showed a brain-to-blood ratio greater than 20:1 in rats, supporting that hexyl lipophilic substitution is compatible with high brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "CB13, a lipophilic pentyloxy aryl ketone, was peripherally restricted with low brain concentrations, showing that lipophilicity alone does not guarantee CNS access; but its larger fused aromatic system and different pharmacophore limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's N-methyltetrahydropyridine heteroaromatic scaffold is represented by permeable analogues Lu 25-109 and CI-979, and the hexyloxy substituent adds lipophilicity; the main contradictory analogue lacks this lipophilic group and is an acidic tetrazole, so the balance favors meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "No explicit efflux transporter or unbound brain concentration data for the query.",
    "Morgan similarities to the closest evidence molecules are moderate, not high."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

